        "unit_id": null
      },
      "tare_balancing_reference": {
        "value": "Max"
      },
      "tare_balancing_mode": {
        "value": "subtractive"
      },
      "preset_tare_range": {
        "value": { "min": null, "max": 100 },
        "unit_symbol": "%",
        "unit_id": null,
        "footnote_markers": ["1)"]
      },
      "preset_tare_reference": {
        "value": "Max"
      }
