          },
          {
            "condition": "(IIII)",
            "value": 1000,
            "unit_symbol": null,
            "footnote_markers": ["1)"]
          }
        ]
      }
    ]
  },
  "matrix_tables": [
    {
      "name": "Table 1 - Limiting values for selectable weighing ranges",
      "columns": ["accuracy_class", "max", "number_of_verification_intervals", "temperature_range", "tare_balancing_range", "preset_tare_range"],
      "column_units": [null, null, null, "°C", "%", "%"],
      "rows": [
        {
          "accuracy_class": "(III)",
          "max": "0.3 kg to 400 t",
          "number_of_verification_intervals": 6000,
          "temperature_range": "-10 to +40",
          "tare_balancing_range": "≤ 100 % of Max (subtractive)",
          "preset_tare_range": "≤ 100 % of Max (1)"
        },
        {
          "accuracy_class": "(IIII)",
          "max": "0.3 kg to 400 t",
          "number_of_verification_intervals": 1000,
          "temperature_range": "-10 to +40",
          "tare_balancing_range": "≤ 100 % of Max (subtractive)",
          "preset_tare_range": "≤ 100 % of Max (1)"
        }
      ],
      "description": "The weighing ranges comprising Max, verification scale intervals, number of verification scale intervals and scale intervals may be selected considering the limiting values in table 1. Max and temperature range apply to both accuracy classes; the number of verification intervals differs per class.",
      "footnotes": ["1) this applies to each range of single- and multiple range instruments"]
    }
  ],
  "recommendation": {
    "id": "R76",
    "edition": 1992,
    "amendment": "Amendment 1 (1994)",
    "accuracy_classes": ["III", "IIII"]
